sparql:
SELECT (xsd:decimal(?paidCount) / ?totalCount * 100 AS ?percentage_not_free)

FROM <https://omnix.dev/graphs/demo-tenant/kg/events-sf>
WHERE {
    {
        SELECT (COUNT(DISTINCT ?event) AS ?totalCount)
        WHERE {
            ?event a <https://omnix.dev/types/Event> .
            ?event <https://omnix.dev/onto/event_category> ?category .
            ?category <https://omnix.dev/types/EventCategory/attrs/name> "Business & Entrepreneurship" .
        }
    }
    {
        SELECT (COUNT(DISTINCT ?event) AS ?paidCount)
        WHERE {
            ?event a <https://omnix.dev/types/Event> .
            ?event <https://omnix.dev/onto/event_category> ?category .
            ?category <https://omnix.dev/types/EventCategory/attrs/name> "Business & Entrepreneurship" .
            ?event <https://omnix.dev/types/Event/attrs/is_free> false .
        }
    }
}
